mapper.select:
SELECT
id, customer, frame, time, number, type,
total, cost, examine, cse, check_status, user, data
FROM other_out_list



        AND number LIKE CONCAT('%', #{query.number}, '%')



        AND examine = #{query.examine}



        AND frame = #{query.frame}



        AND time >= #{query.startTime}


        AND time <= #{query.endTime}



        AND user = #{query.user}


ORDER BY time DESC
